import{A as Ha,kt as aE,u as Ba,zt as dv}from"./chunk-DAO4mTyP.js";var r=(()=>{class i{static{this.ɵfac=function(t){return new(t||i)}}static{this.ɵcmp=dv({type:i,selectors:[[`ctl-codigo-conduta`]],decls:151,vars:0,consts:[[1,`plain-page`,`wrap`],[1,`plain-page-heading`],[1,`legal`],[1,`legal-heading`],[1,`legal-subheading`],[1,`legal-note`]],template:function(t,n){t&1&&(Ha(0,`article`,0)(1,`h1`,1),aE(2,`Código de Conduta para Prevenção e Combate ao Assédio no Trabalho`),Ba(),Ha(3,`div`,2)(4,`p`),aE(5,`A Lei n.º 73/2017, de 16 de agosto de 2017, a vigorar desde 1 de outubro 2017, vem reforçar o quadro legislativo para a prevenção da prática de assédio no trabalho, tanto no setor privado como na Administração Pública.`),Ba(),Ha(6,`h2`,3),aE(7,`Preâmbulo`),Ba(),Ha(8,`p`),aE(9,`O presente Código de Conduta visa aumentar a consciência e a compreensão de todos os recursos humanos do Clube de Tempos Livres de Santa Clara (CTL) e facultar um quadro orientador de ação que permita identificar, prevenir, combater e gerir problemas e assédio no trabalho nos termos da Lei 73/2017, de 16 de agosto, e no cumprimento do disposto na alínea k) do n.º 1 do artigo 27.º do Código do Trabalho`),Ha(10,`sup`),aE(11,`1`),Ba(),aE(12,`.`),Ba(),Ha(13,`p`),aE(14,`A Instituição, compromete-se assim, a defender os valores da não discriminação e de combate contra o assédio no trabalho, assumindo este Código de Conduta como instrumento privilegiado na resolução de questões éticas, garantindo a conformidade deste com as práticas legais a que está sujeita.`),Ba(),Ha(15,`h2`,3),aE(16,`Âmbito de aplicação e princípios gerais`),Ba(),Ha(17,`h3`,4),aE(18,`Artigo 1.º (Âmbito de aplicação)`),Ba(),Ha(19,`p`),aE(20,`O presente Código de Conduta aplica-se a todos os membros dos órgãos sociais, colaboradores (qualquer que seja vínculo contratual), utentes e outras pessoas que participem nas suas atividades.`),Ba(),Ha(21,`h3`,4),aE(22,`Artigo 2.º (Princípios gerais)`),Ba(),Ha(23,`ol`)(24,`li`),aE(25,`Os colaboradores e órgãos sociais do CTL, internamente ou em representação externa, devem pautar a sua atuação de acordo com os princípios e valores éticos associados ao CTL adotando comportamentos baseados na responsabilidade, no rigor e no respeito estrito pela dignidade e direitos das pessoas. `),Ba(),Ha(26,`li`),aE(27,`O CTL incentiva o respeito e a cooperação entre todos os colaboradores, num ambiente de trabalho respeitoso e digno, pelo que não são toleradas ou admissíveis quaisquer práticas de assédio. `),Ba()(),Ha(28,`h3`,4),aE(29,`Artigo 3.º (Comportamentos ilícitos)`),Ba(),Ha(30,`ol`)(31,`li`),aE(32,`Considerando o artigo 29.º do Código do Trabalho, “Entende-se por assédio o comportamento indesejado, nomeadamente baseado em fator de discriminação, praticado aquando do acesso ao emprego ou no próprio emprego, trabalho ou formação profissional, com o objetivo ou o efeito de perturbar ou constranger a pessoa, afetar a sua dignidade, ou de lhe criar um ambiente intimidativo, hostil, degradante, humilhante ou desestabilizador. Constitui assédio sexual o comportamento indesejado de carácter sexual, sob forma verbal, não verbal ou física”. `),Ba(),Ha(33,`li`),aE(34,`O assédio constitui uma expressão de comportamentos indesejáveis e/ ou inaceitáveis por parte de um ou mais indivíduos, sendo percebidos como uma prática de perseguição ou maus-tratos, designadamente por causa de ascendência, sexo, nacionalidade, património genético, língua, território de origem, religião, convicções políticas ou ideológicas, filiação sindical, instrução, situação económica, condição social, orientação sexual, deficiência, doença e capacidade de trabalho reduzida e pode assumir diversas formas, algumas das quais mais facilmente identificáveis do que outras. `),Ba(),Ha(35,`li`),aE(36,`O assédio ocorre quando um ou mais trabalhadores ou quadros dirigentes são repetida e deliberadamente intimidados, ameaçados e/ou humilhados em circunstâncias relacionadas com o trabalho. O assédio pode ser levado a cabo por um ou mais quadros dirigentes, colegas ou terceiros, com o propósito ou efeito de violar a dignidade de um quadro dirigente ou trabalhador/a, afetando a sua saúde e/ou que se traduz num ambiente de trabalho intimidativo, hostil, degradante, humilhante ou desestabilizador, que pretendem levar a vítima a um determinado comportamento ou ao seu afastamento/marginalização. O assédio no trabalho compreende comportamentos que, quando analisados isoladamente, até podem não ser considerados ilícitos, no entanto se considerados no seu conjunto são aptos a criar no/a trabalhador/a um desconforto e mal-estar no trabalho que ferem a respetiva dignidade profissional, integridade moral e psíquica, a tal ponto de poderem ter reflexos na prestação laboral e na própria saúde do/a trabalhador/a. `),Ba(),Ha(37,`li`),aE(38,`Assim sendo, são expressamente proibidos os seguintes comportamentos suscetíveis de serem considerados como assédio no trabalho: `),Ha(39,`ol`)(40,`li`),aE(41,`Comportamento degradante, ofensivo, insultuoso, intimidante, embaraçoso ou humilhante;`),Ba(),Ha(42,`li`),aE(43,`Ridicularizar, de forma direta ou indireta, uma característica física ou psicológica;`),Ba(),Ha(44,`li`),aE(45,`Falar constantemente aos gritos, de forma a intimidar as pessoas;`),Ba(),Ha(46,`li`),aE(47,`Segmentar um indivíduo com tratamento diferenciado de uma natureza irritante;`),Ba(),Ha(48,`li`),aE(49,`Impedimento do desempenho / sabotagem do trabalho;`),Ba(),Ha(50,`li`),aE(51,`Espalhar rumores, incluindo ciberbullying;`),Ba(),Ha(52,`li`),aE(53,`Toques sexuais inapropriados, avanços, sugestões ou pedidos;`),Ba(),Ha(54,`li`),aE(55,`Exibição ou circulação de imagens ou materiais ofensivos em formato eletrónico ou impresso que são conhecidos ou que devem ser reconhecidos como ofensivos; `),Ba(),Ha(56,`li`),aE(57,`Promover o isolamento social.`),Ba()()(),Ha(58,`li`),aE(59,`O assédio no local de trabalho não representa nem pretende impedir que os empregadores disciplinem ou procedam à gestão dos seus trabalhadores. Assim, o assédio no local de trabalho não inclui, nomeadamente: `),Ha(60,`ol`)(61,`li`),aE(62,`Gestão de desempenho;`),Ba(),Ha(63,`li`),aE(64,`Pressão decorrente do exercício das funções;`),Ba(),Ha(65,`li`),aE(66,`Exercício de autoridade e do poder disciplinar;`),Ba(),Ha(67,`li`),aE(68,`Requisitos ou decisões operacionais;`),Ba(),Ha(69,`li`),aE(70,`Um desentendimento ou mal-entendido;`),Ba(),Ha(71,`li`),aE(72,`Mudança relacionada ao trabalho (v.g., mudança de localização, de colegas de trabalho ou trabalho ocupacional); `),Ba(),Ha(73,`li`),aE(74,`Um único comentário ou ação, a menos que tenha efeitos graves, prejudiciais e duradouros;`),Ba(),Ha(75,`li`),aE(76,`Elogios ocasionais.`),Ba()()()(),Ha(77,`h3`,4),aE(78,`Artigo 4.º (Infração disciplinar e sanções)`),Ba(),Ha(79,`ol`)(80,`li`),aE(81,`Em caso de eventual situação de assédio, que não se tolera, o procedimento a desenvolver internamente baseia-se nos seguintes princípios: `),Ha(82,`ol`)(83,`li`),aE(84,`O interesse de todas as partes em agir com a discrição necessária para proteger a dignidade e a privacidade de cada um; `),Ba(),Ha(85,`li`),aE(86,`A não divulgação de qualquer informação a outras partes não envolvidas no incidente;`),Ba(),Ha(87,`li`),aE(88,`As queixas devem ser investigadas e tratadas com o máximo de segredo e celeridade;`),Ba(),Ha(89,`li`),aE(90,`Todas as partes envolvidas devem ser ouvidas de forma imparcial e beneficiar de um tratamento equitativo; `),Ba(),Ha(91,`li`),aE(92,`As queixas devem ser sustentadas com base em informações detalhadas;`),Ba(),Ha(93,`li`),aE(94,`Caso seja provada a ocorrência de assédio, serão tomadas medidas adequadas contra o(s) que o tenha(m) levado a cabo, as quais poderão compreender sanções disciplinares aí incluído o despedimento; `),Ba(),Ha(95,`li`),aE(96,`Os autores de acusações falsas poderão ser alvo de processos disciplinares. Em caso de eventual situação de assédio, pode haver uma abordagem informal ou um procedimento formal. `),Ba()()(),Ha(97,`li`),aE(98,`Em alguns casos pode ser efetuada uma abordagem preliminar na correção de algumas situações sem se percorrer todos os formalismos inerentes ao procedimento disciplinar. Por vezes, as pessoas não sabem que seu comportamento não é adequado, bem-vindo ou rejeitável, e uma abordagem direta, frontal e imediata, que também inclua os intervenientes, pode conduzir a um entendimento sobre o ocorrido e quanto à cessação do comportamento. Nestes casos, os intervenientes, se assim o entenderem, podem enveredar por esta abordagem, comunicando e solicitando o apoio da sua chefia direta, ou outro elemento da sua estrutura hierárquica ou, ainda, outro colaborador da organização. Na sequência dessa abordagem, a entidade empregadora deve desenvolver medidas preventivas apropriadas para: eliminar comportamentos, evitar danos. O empregador, como pessoa responsável pelo bem-estar dos trabalhadores, decide as medidas que toma (ou não) e informa a pessoa afetada por essas medidas no prazo de 10 dias úteis. `),Ba(),Ha(99,`li`),aE(100,`Em caso de alegação de assédio é aberto um procedimento disciplinar que, sem prejuízo das regras constantes no Código do Trabalho, obedecerá ao seguinte: `),Ha(101,`ol`)(102,`li`),aE(103,`Sempre que a entidade empregadora tome conhecimento da violação das disposições constantes do presente Código de Conduta procederá à abertura de um procedimento disciplinar, no prazo máximo de um ano, sem prejuízo da responsabilidade civil, contraordenacional ou criminal a que haja lugar; `),Ba(),Ha(104,`li`),aE(105,`A Direção e os seus colaboradores denunciarão quaisquer práticas irregulares de que tenham conhecimento, prestando a devida colaboração em eventuais processos disciplinares ou de investigação criminal pelas respetivas entidades competentes. `),Ba(),Ha(106,`li`),aE(107,`O procedimento interno deve ser circunscrito ao conhecimento dos envolvidos.`),Ba(),Ha(108,`li`),aE(109,`O CTL elabora um relatório com base nos factos que lhe foi possível apurar, incluído os factos e seu enquadramento jurídico indicando, se possível, circunstâncias agravantes ou atenuantes, e propondo à Direção do CTL a tomada da decisão final. `),Ba()()()(),Ha(110,`h3`,4),aE(111,`Artigo 5.º (Regime de proteção ao denunciante e testemunhas)`),Ba(),Ha(112,`ol`)(113,`li`),aE(114,`Será garantido um regime específico de proteção para o denunciante e as testemunhas em procedimentos relacionados com situações de assédio. `),Ba(),Ha(115,`li`),aE(116,`Presume-se abusivo o despedimento ou outra sanção aplicada alegadamente para punir uma infração, até um ano após a denúncia ou outra forma de exercício de direitos relativos a igualdade, não discriminação e assédio. `),Ba(),Ha(117,`li`),aE(118,`É garantida a atribuição de proteção especial aos denunciantes e testemunhas em processos judiciais ou contraordenacionais desencadeados por assédio, não podendo os mesmos ser sancionados disciplinarmente salvo quando atuem com dolo. `),Ba(),Ha(119,`li`),aE(120,`Os colaboradores da Instituição que denunciem o cometimento de infrações ao presente Código, de que tiverem conhecimento no exercício das suas funções ou por causa delas, não podem, sob qualquer forma, ser prejudicados, sendo-lhes assegurado o anonimato até à dedução de acusação. `),Ba()(),Ha(121,`h3`,4),aE(122,`Artigo 6.º (Publicidade da decisão)`),Ba(),Ha(123,`p`),aE(124,`Garante-se a impossibilidade de dispensa da sanção acessória de publicidade da decisão condenatória quando esteja em causa a prática de assédio que constitui contraordenação muito grave podendo gerar responsabilidade penal.`),Ba(),Ha(125,`h3`,4),aE(126,`Artigo 7.º (Responsabilidade do empregador)`),Ba(),Ha(127,`p`),aE(128,`O Empregador é responsável pela reparação dos danos emergentes de doenças profissionais resultantes da prática de assédio, que será fixada em regulamentação própria, ficando esta indemnização sub-rogada nos direitos do trabalhador.`),Ba(),Ha(129,`h3`,4),aE(130,`Artigo 8.º (Comunicação de queixas de assédio em contexto laboral)`),Ba(),Ha(131,`ol`)(132,`li`),aE(133,`Nos termos de regulamentação própria, serão disponibilizados e divulgados pela Autoridade para as Condições do Trabalho os endereços eletrónicos próprios para receção de queixas de assédio em contexto laboral; `),Ba(),Ha(134,`li`),aE(135,`A prática de assédio pelo empregador ou por algum representante do mesmo, denunciada à Autoridade para as Condições no Trabalho (ACT), figurará entre os exemplos de justa causa de resolução do contrato de trabalho por parte do trabalhador. `),Ba(),Ha(136,`li`),aE(137,`Em qualquer caso, a vítima pode apresentar queixa na Comissão para a Igualdade no Trabalho e no Emprego (CITE), Autoridade para as Condições de Trabalho (ACT) ou na entidade competente para receção da queixa, consoante a natureza do comportamento em causa. `),Ba()(),Ha(138,`h2`,3),aE(139,`Disposições finais`),Ba(),Ha(140,`h3`,4),aE(141,`Artigo 9.º (Divulgação, compromisso e aplicação)`),Ba(),Ha(142,`ol`)(143,`li`),aE(144,`O presente Código de Conduta entra em vigor imediatamente após a sua aprovação pela Direção e a sua divulgação a todos os Colaboradores; `),Ba(),Ha(145,`li`),aE(146,`No processo de admissão dos Colaboradores deverá constar a declaração de conhecimento e aceitação das normas vigentes no presente Código de Conduta. `),Ba()(),Ha(147,`p`,5)(148,`sup`),aE(149,`1`),Ba(),aE(150,` Adotar códigos de boa conduta para a prevenção e combate ao assédio no trabalho, sempre que a empresa tenha sete ou mais trabalhadores.`),Ba()()())},encapsulation:2})}}return i})();export{r as CodigoCondutaComponent};